"""ODMM V205.7 — cockpit read-only collection integration. Auteur: Abdelhalim Talbi."""
import base64
import hashlib
import re
from odmm_capability_cockpit_v2051 import PAGE as PREVIOUS

PANEL='''<section id="collection-v2057"><h2>Collecte constructeur · V205.7</h2><p class="muted">Collecte HTTPS en lecture seule, avec autorisation serveur obligatoire. Aucun identifiant n'est saisi dans le navigateur.</p><div class="cards"><div class="card">Origine de preuve<strong id="coll-origin">NO_EVIDENCE</strong></div><div class="card">État<strong id="coll-state">UNVERIFIED</strong></div><div class="card">Décision<strong id="coll-gate">CUTOVER INTERDIT</strong></div></div><label>Constructeur <select id="coll-vendor"><option value="netapp_ontap">NetApp ONTAP</option><option value="dell_powerscale">Dell PowerScale</option></select></label><label>Hôte autorisé <input id="coll-host" placeholder="nas.example.org" maxlength="253"></label><button id="coll-start" type="button">Interroger le NAS (lecture seule)</button><label>Importer un rapport V205.6 <input id="coll-file" type="file" accept=".json,application/json"></label><p id="coll-feedback" role="status" aria-live="polite">Aucune collecte exécutée. Les imports restent non certifiés.</p><table><thead><tr><th>Attribut</th><th>Valeur</th></tr></thead><tbody id="coll-rows"></tbody></table></section>'''
SCRIPT='''<script>
'use strict';(()=>{const el=id=>document.getElementById(id);const fields=['vendor','host','endpoint','collected_at','response_sha256','provenance','status'];function reset(){el('coll-origin').textContent='NO_EVIDENCE';el('coll-state').textContent='UNVERIFIED';el('coll-gate').textContent='CUTOVER INTERDIT';el('coll-rows').replaceChildren()}function render(report,origin){reset();if(!report||report.schema!=='odmm.collection.v2056'||report.status!=='UNVERIFIED'||report.cutover_authorized!==false||report.acl_fidelity_verified!==false||report.effective_access_verified!==false||!['netapp_ontap','dell_powerscale'].includes(report.vendor)||typeof report.response_sha256!=='string'||!/^[0-9a-f]{64}$/.test(report.response_sha256))throw Error('Rapport non conforme');for(const field of fields){const v=report[field];if(typeof v!=='string'||v.length>512)throw Error('Champ invalide: '+field);const tr=document.createElement('tr');for(const s of [field,v]){const td=document.createElement('td');td.textContent=s;tr.appendChild(td)}el('coll-rows').appendChild(tr)}el('coll-origin').textContent=origin;el('coll-state').textContent='UNVERIFIED';el('coll-feedback').textContent='Provenance déclarée: '+origin+' · ACL non certifiées · Cutover interdit'}el('coll-file').addEventListener('change',async e=>{reset();try{const file=e.target.files[0];if(!file)return;if(file.size>1048576)throw Error('Fichier supérieur à 1 Mio');render(JSON.parse(await file.text()),'IMPORT LOCAL NON CERTIFIÉ')}catch(err){el('coll-feedback').textContent='Import refusé: '+err.message}});el('coll-start').addEventListener('click',async()=>{reset();el('coll-feedback').textContent='Collecte demandée';try{const vendor=el('coll-vendor').value,host=el('coll-host').value.trim();if(!/^[a-zA-Z0-9][a-zA-Z0-9.-]{0,252}$/.test(host)||host.includes('..'))throw Error('Nom hôte invalide');const r=await fetch('/api/v1/qualification/collect',{method:'POST',credentials:'same-origin',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify({vendor,host})});if(!r.ok)throw Error('Accès refusé ou collecte indisponible (HTTP '+r.status+')');const data=await r.json();if(data.host!==host||data.vendor!==vendor)throw Error('Réponse incohérente');render(data,'API AUTHENTIFIÉE (NON CERTIFIÉE)')}catch(err){el('coll-feedback').textContent=err.message+' · Cutover interdit'}})})();
</script>'''
PAGE=PREVIOUS.replace('</main>',PANEL+'</main>').replace('</body>',SCRIPT+'</body>').replace('V205.1','V205.7')
def cockpit_csp():
    tags=[(tag,body) for tag in ('script','style') for body in re.findall(r'<'+tag+r'>(.*?)</'+tag+r'>',PAGE,re.S)]
    def hashes(tag):return ' '.join("'sha256-"+base64.b64encode(hashlib.sha256(body.encode()).digest()).decode()+"'" for t,body in tags if t==tag)
    return "default-src 'none'; connect-src 'self'; script-src "+hashes('script')+'; style-src '+hashes('style')+"; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"

def attach_collection_cockpit(app,*,authorize):
    if not callable(authorize):raise ValueError('AUTHORIZATION_PROVIDER_REQUIRED')
    from fastapi import Request,HTTPException
    from fastapi.responses import HTMLResponse
    async def page(request:Request):
        if authorize(request) is not True:raise HTTPException(403,'FORBIDDEN')
        return HTMLResponse(PAGE,headers={'Content-Security-Policy':cockpit_csp(),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'})
    app.add_api_route('/qualification/cockpit',page,methods=['GET'],include_in_schema=False)
